    {
      "path": "src/anchors.ts",
      "content": "/**\n * Hard-fact extraction — the input side of the fidelity gate.\n *\n * An \"anchor\" is a piece of the user's draft that carries information the rewrite\n * has no licence to drop or paraphrase: paths, identifiers, numbers, URLs, inline\n * code, @references. The gate is deliberately DETERMINISTIC (no model call): it\n * extracts anchors from the draft, then verifies each one literally survives.\n *\n * @module dsh-smart-prompt/anchors\n */\n\n/** What kind of hard fact an anchor is. */\nexport type AnchorKind = 'code' | 'url' | 'path' | 'ref' | 'version' | 'number' | 'identifier'\n\n/** One extracted hard fact. */\nexport interface Anchor {\n  /** Exact text as it appeared in the draft (minus markup such as backticks). */\n  readonly text: string\n  readonly kind: AnchorKind\n}\n\n/** Maximum anchors tracked; beyond this the gate reports honestly rather than growing unbounded. */\nconst MAX_ANCHORS = 200\n/** Anchors shorter than this are noise (single letters, one-digit numbers). */\nconst MIN_LENGTH = 2\n/** Cap for one kept span. */\nconst MAX_CODE_LENGTH = 120\n\nconst FILE_EXTENSIONS = [\n  'ts', 'tsx', 'js', 'jsx', 'mjs', 'cjs', 'd', 'py', 'rb', 'go', 'rs', 'java', 'kt', 'kts',\n  'c', 'h', 'cc', 'cpp', 'hpp', 'cs', 'php', 'swift', 'm', 'mm', 'scala', 'sh', 'bash', 'zsh',\n  'ps1', 'bat', 'sql', 'md', 'mdx', 'txt', 'log', 'json', 'jsonc', 'yaml', 'yml', 'toml', 'ini',\n  'cfg', 'conf', 'env', 'lock', 'gradle', 'properties', 'xml', 'html', 'htm', 'css', 'scss',\n  'less', 'vue', 'svelte', 'astro', 'proto', 'tf', 'dockerfile', 'makefile', 'ipynb', 'csv',\n].join('|')\n\ninterface Matcher {\n  readonly kind: AnchorKind\n  readonly pattern: RegExp\n  /** Claim the span without recording it: used for fenced blocks, which are payload, not a fact. */\n  readonly claimOnly?: boolean\n}\n\n/**\n * Ordered matchers; earlier matchers claim their spans so later ones cannot re-read\n * them. A fenced code block is CLAIMED but not recorded — it is normally the payload\n * the user pasted, not a fact the surrounding prose must reproduce — while an inline\n * \\`code\\` span is short, specific, and always recorded.\n */\nconst MATCHERS: ReadonlyArray<Matcher> = [\n  { kind: 'code', pattern: /```[\\s\\S]*?```/g, claimOnly: true },\n  { kind: 'code', pattern: /`[^`\\n]+`/g },\n  { kind: 'url', pattern: /https?:\\/\\/[^\\s<>()[\\]\"'`]+/g },\n  { kind: 'ref', pattern: /(?:^|[\\s(\\[{,，。；;])@([A-Za-z0-9_][A-Za-z0-9_./-]{1,})/g },\n  // any path with at least one separator: absolute, drive-lettered, ./-relative, or bare-relative\n  { kind: 'path', pattern: /(?:[A-Za-z]:)?(?:\\/|\\.{1,2}\\/)?[A-Za-z0-9_.@-]+(?:\\/[A-Za-z0-9_.@*-]+)+/g },\n  // bare file names carrying a known extension\n  { kind: 'path', pattern: new RegExp('\\\\b[A-Za-z0-9_@-][A-Za-z0-9_.@-]*\\\\.(?:' + FILE_EXTENSIONS + ')\\\\b', 'gi') },\n  { kind: 'version', pattern: /\\bv?\\d+(?:\\.\\d+){1,3}(?:-rc\\.?\\d*)?\\b/gi },\n  { kind: 'number', pattern: /\\b\\d+(?:\\.\\d+)?\\s?(?:%|px|em|rem|ms|s|m|h|kb|mb|gb|tb|k|w|次|个|秒|分钟|小时|天|行|条|页)\\b/gi },\n  // dotted paths first: they must claim the whole token before camelCase reads a segment\n  { kind: 'identifier', pattern: /\\b[a-z][A-Za-z0-9]*(?:\\.[a-z][A-Za-z0-9]*){1,4}\\b/g },\n  { kind: 'identifier', pattern: /\\b[a-z][a-zA-Z0-9]*(?:[A-Z][A-Za-z0-9]*)+\\b/g },\n  { kind: 'identifier', pattern: /\\b[a-z][a-z0-9]*(?:_[a-z0-9]+)+\\b/g },\n  { kind: 'identifier', pattern: /\\b[A-Z][A-Z0-9]*(?:_[A-Z0-9]+)+\\b/g },\n]\n\n/** Strip the markup a matcher matched around the fact itself. */\nfunction unwrap(kind: AnchorKind, raw: string): string {\n  let text = raw\n  if (kind === 'code') text = text.replace(/^`|`$/g, '')\n  if (kind === 'ref') {\n    const at = text.indexOf('@')\n    text = at >= 0 ? text.slice(at) : text\n  }\n  return text.trim()\n}\n\n/**\n * Extract every hard fact from one draft.\n *\n * Overlapping matchers are resolved first-wins on the text range, so a path inside\n * backticks is recorded once as \\`code\\` — the stronger requirement, since the rewrite\n * must then reproduce the backticked span exactly.\n *\n * @param draft - the user's raw composer text.\n * @param limit - maximum anchors to return.\n * @returns anchors in first-appearance order, de-duplicated.\n */\nexport function extractAnchors(draft: string, limit = MAX_ANCHORS): Anchor[] {\n  const text = typeof draft === 'string' ? draft : ''\n  if (text === '') return []\n  const claimed = new Array<boolean>(text.length).fill(false)\n  const seen = new Set<string>()\n  const out: Anchor[] = []\n\n  for (const { kind, pattern, claimOnly } of MATCHERS) {\n    const re = new RegExp(pattern.source, pattern.flags)\n    let match: RegExpExecArray | null\n    while ((match = re.exec(text)) !== null) {\n      if (match[0] === '') { re.lastIndex += 1; continue }\n      const start = match.index\n      const end = start + match[0].length\n      let free = true\n      for (let i = start; i < end; i += 1) {\n        if (claimed[i] === true) { free = false; break }\n      }\n      if (!free) continue\n      for (let i = start; i < end; i += 1) claimed[i] = true\n      if (claimOnly === true) continue\n      const value = unwrap(kind, match[0])\n      if (value.length < MIN_LENGTH || value.length > MAX_CODE_LENGTH) continue\n      const key = kind + '\\u0000' + value\n      if (seen.has(key)) continue\n      seen.add(key)\n      out.push({ text: value, kind })\n      if (out.length >= limit) return out\n    }\n  }\n  return out\n}\n\n/** Collapse whitespace so a fact that merely moved onto another line still matches. */\nexport function normalizeForMatch(text: string): string {\n  return text.replace(/\\s+/g, ' ')\n}\n\n/** Remove whitespace entirely: catches a token the model wrapped across a line break. */\nexport function stripWhitespace(text: string): string {\n  return text.replace(/\\s+/g, '')\n}\n\n/**\n * Decide whether one anchor survives in the rewrite.\n *\n * Three passes, cheapest first: exact substring, whitespace-collapsed, then\n * whitespace-stripped. The bias is deliberate — reporting a kept fact as missing\n * would cost a needless repair call, while reporting a dropped fact as kept only\n * costs a repair the deterministic re-append still guarantees. Case stays\n * significant: \\`Foo\\` and \\`foo\\` are different identifiers in most languages.\n *\n * @param anchor - the extracted hard fact.\n * @param normalizedEnhanced - the rewrite through {@link normalizeForMatch}.\n * @param rawEnhanced - the rewrite as produced.\n * @param strippedEnhanced - the rewrite through {@link stripWhitespace}.\n * @returns whether the fact survived.\n */\nexport function anchorSurvives(\n  anchor: Anchor,\n  normalizedEnhanced: string,\n  rawEnhanced: string,\n  strippedEnhanced?: string,\n): boolean {\n  if (rawEnhanced.includes(anchor.text)) return true\n  if (normalizedEnhanced.includes(normalizeForMatch(anchor.text))) return true\n  const stripped = strippedEnhanced !== undefined ? strippedEnhanced : stripWhitespace(rawEnhanced)\n  return stripped.includes(stripWhitespace(anchor.text))\n}\n"
    },
    {
      "path": "src/length-gate.ts",
      "content": "/**\n * Length gate — the deterministic answer to the industry's most common failure:\n * a one-line request that comes back as a thirty-line specification.\n *\n * The instrument is a RATIO with an ABSOLUTE FLOOR, because a pure ratio is wrong\n * at both ends: a 2.5x ceiling would let a 2000-character draft grow by 3000 more,\n * while the same 2.5x would refuse a nine-character draft the three-line rewrite it\n * most needs. Below {@link MIN_BUDGET_CHARS} characters the floor governs; above it\n * the mode's ratio governs. WorkBuddy's own positioning (\"less filler, fewer\n * tokens\", a flat ~800-character budget) is the same instinct.\n *\n * @module dsh-smart-prompt/length-gate\n */\n\n/**\n * Absolute character budget below which the ratio does not apply.\n *\n * Sized so a terse draft can still come back as a short structured prompt\n * (deliverable + constraints + acceptance) rather than being refused its own\n * improvement.\n */\nexport const MIN_BUDGET_CHARS = 600\n\n/** Verdict of one length measurement. */\nexport type LengthVerdict =\n  | { readonly kind: 'ok'; readonly ratio: number }\n  | { readonly kind: 'converge'; readonly ratio: number; readonly charBudget: number }\n\n/** Codepoint length — matches what the user sees and counts, not UTF-16 units. */\nexport function charLength(text: string): number {\n  let count = 0\n  for (const _ of text) count += 1\n  return count\n}\n\n/**\n * Ratio of the rewrite to the draft.\n *\n * An empty draft has no meaningful ratio; report 0 so callers never divide by zero.\n *\n * @param original - the user's draft.\n * @param enhanced - the rewrite.\n * @returns enhanced length divided by original length.\n */\nexport function ratioOf(original: string, enhanced: string): number {\n  const base = charLength(original)\n  if (base === 0) return 0\n  return charLength(enhanced) / base\n}\n\n/**\n * The character budget a rewrite of this draft is allowed.\n *\n * @param original - the user's draft.\n * @param maxRatio - ceiling for the active mode; 0 (or less) means uncapped.\n * @returns max({@link MIN_BUDGET_CHARS}, draft length x ratio), or Infinity when uncapped.\n */\nexport function budgetFor(original: string, maxRatio: number): number {\n  if (!(maxRatio > 0)) return Number.POSITIVE_INFINITY\n  return Math.max(MIN_BUDGET_CHARS, Math.floor(charLength(original) * maxRatio))\n}\n\n/**\n * Is this rewrite over budget?\n *\n * @param original - the user's draft.\n * @param enhanced - the rewrite.\n * @param maxRatio - ceiling for the active mode.\n * @returns whether the rewrite exceeds {@link budgetFor}.\n */\nexport function overBudget(original: string, enhanced: string, maxRatio: number): boolean {\n  return charLength(enhanced) > budgetFor(original, maxRatio)\n}\n\n/**\n * Judge a rewrite against the mode's ceiling.\n *\n * @param original - the user's draft.\n * @param enhanced - the rewrite.\n * @param maxRatio - ceiling for the active mode.\n * @returns `ok`, or `converge` carrying the character budget for one repair attempt.\n */\nexport function lengthVerdict(original: string, enhanced: string, maxRatio: number): LengthVerdict {\n  const ratio = ratioOf(original, enhanced)\n  const budget = budgetFor(original, maxRatio)\n  if (charLength(enhanced) <= budget) return { kind: 'ok', ratio }\n  return { kind: 'converge', ratio, charBudget: budget }\n}\n\n/**\n * The repair instruction for a rewrite over its budget, appended to the user message of\n * the single repair call.\n *\n * @param actualChars - the rewrite's length.\n * @param charBudget - the budget it exceeded.\n * @returns the instruction text.\n */\nexport function lengthRepairClause(actualChars: number, charBudget: number): string {\n  return '\\nYour previous rewrite was too long: ' + String(actualChars)\n    + ' characters against a budget of ' + String(charBudget)\n    + '. Rewrite it again, shorter, without dropping any content.'\n}\n\n/** Round for display: 1.44 -> \"1.4x\". */\nexport function formatRatio(ratio: number): string {\n  return (Math.round(ratio * 10) / 10).toFixed(1) + 'x'\n}\n"
    },
    {
      "path": "src/attachments.ts",
      "content": "/**\n * The draft's own attachments, read into model content blocks for the refinement call.\n *\n * The composer posts them in its command wire form (`serializeDraftAttachments`): images\n * as base64, other files as receipts of their finished background uploads. Images go\n * through the host's own prompt admission, so the refinement model sees exactly what the\n * agent will; files are read here and inlined as text, because the refinement model has\n * no file tools to open the saved copy a file block would point it to.\n *\n * Host services are passed in structurally, which keeps this module free of cordis and\n * testable with stubs.\n *\n * @module dsh-smart-prompt/attachments\n */\n\nimport { escapeClosingTag } from './prompts.js'\nimport { asRecord } from './values.js'\n\n/** The host services attachment reading needs. */\nexport interface AttachmentServices {\n  /** `ctx.attachments.admitPromptContent`: validates and stores images, passes file refs through. */\n  admit(parts: readonly unknown[]): Promise<readonly unknown[]>\n  /**\n   * `ctx.fileUploads.resolve` for the session's agent; undefined for an unknown receipt.\n   * DSH 0.2.1 returns the file reference itself; DSH 0.2.2 returns the staged attachment\n   * (`{ type: 'file' | 'image', attachment, … }`). {@link readAttachments} accepts both.\n   */\n  resolveFile(sessionId: string, receiptId: string): unknown\n  /** `ctx.attachments.readFileStream`: the stored file's bytes, in chunks. */\n  readFile(ref: unknown, signal: AbortSignal): AsyncIterable<Uint8Array>\n}\n\n/** Bytes read from one file; the rest is left to the agent, who gets the whole file. */\nconst FILE_BYTES = 64 * 1024\n/** Characters of one file's text shown to the refinement model. */\nconst FILE_CHARS = 20000\n/** Characters of file text across all attachments of one draft. */\nconst TOTAL_FILE_CHARS = 60000\n\ninterface FileRef { readonly name?: unknown; readonly bytes?: unknown }\ninterface WireItem { readonly type?: unknown; readonly mediaType?: unknown; readonly data?: unknown; readonly name?: unknown; readonly receiptId?: unknown }\ninterface AdmittedPart { readonly type?: unknown; readonly attachment?: unknown }\ninterface StagedPart { readonly type?: unknown; readonly attachment?: unknown }\n\n/**\n * The admission part for one resolved receipt. A staged attachment (DSH 0.2.2+) carries its\n * kind and passes to admission as it is; a bare file reference (DSH 0.2.1, which has no\n * `type` field) becomes a file part.\n */\nfunction receiptPart(resolved: unknown): unknown {\n  const staged = resolved as StagedPart\n  if ((staged.type === 'file' || staged.type === 'image') && staged.attachment !== undefined && staged.attachment !== null) return resolved\n  return { type: 'file', attachment: resolved }\n}\n\n/**\n * Read the draft's attachments, in the order the user added them.\n *\n * @param services - host attachment services.\n * @param sessionId - the session whose composer holds the attachments (file receipts are per session).\n * @param wire - the attachments as the composer serialized them.\n * @param signal - cancels file reads.\n * @returns image blocks and file-text blocks, in attachment order.\n * @throws Error when an attachment is malformed, no longer staged, or refused by admission.\n */\nexport async function readAttachments(services: AttachmentServices, sessionId: string, wire: readonly unknown[], signal: AbortSignal): Promise<unknown[]> {\n  const parts = wire.map((raw): unknown => {\n    const item = asRecord(raw) as WireItem\n    if (item.type === 'image' && typeof item.mediaType === 'string' && typeof item.data === 'string') {\n      return { type: 'image', mediaType: item.mediaType, data: item.data, ...(typeof item.name === 'string' && item.name !== '' ? { name: item.name } : {}) }\n    }\n    if (item.type === 'file' && typeof item.receiptId === 'string') {\n      const attachment = services.resolveFile(sessionId, item.receiptId)\n      if (attachment === undefined || attachment === null) throw new Error('an attached file is no longer available; attach it again')\n      return receiptPart(attachment)\n    }\n    throw new Error('unsupported attachment')\n  })\n  const admitted = await services.admit(parts)\n  const blocks: unknown[] = []\n  let budget = TOTAL_FILE_CHARS\n  for (const raw of admitted) {\n    const part = (raw ?? {}) as AdmittedPart\n    if (part.type === 'image') {\n      blocks.push(Object.freeze({ type: 'image', attachment: part.attachment }))\n    } else if (part.type === 'file') {\n      const text = await fileText(services, part.attachment, signal, budget)\n      budget -= text.shown\n      blocks.push(Object.freeze({ type: 'text', text: text.block }))\n    }\n  }\n  return blocks\n}\n\n/** One file as a text block: its content when it is text, otherwise a note naming it. */\nasync function fileText(services: AttachmentServices, ref: unknown, signal: AbortSignal, budget: number): Promise<{ block: string; shown: number }> {\n  const meta = (ref ?? {}) as FileRef\n  const name = typeof meta.name === 'string' ? meta.name : 'file'\n  const size = typeof meta.bytes === 'number' ? meta.bytes : 0\n  const note = (why: string): { block: string; shown: number } =>\n    ({ block: '[Attached file \"' + name + '\" (' + String(size) + ' bytes): ' + why + ']', shown: 0 })\n  if (budget <= 0) return note('content not shown, the attachments are too long to show in full')\n\n  const head = await readHead(services.readFile(ref, signal), FILE_BYTES)\n  const text = decodeText(head, size > head.length)\n  if (text === null) return note('not plain text, content not shown')\n  const limit = Math.min(FILE_CHARS, budget)\n  const shown = text.length <= limit ? text : text.slice(0, limit)\n  const truncated = shown.length < text.length || size > head.length\n  return {\n    block: '<attached_file name=\"' + escapeAttribute(name) + '\" bytes=\"' + String(size) + '\">\\n' + escapeClosingTag(shown)\n      + (truncated ? '\\n… (truncated here; the agent receives the whole file)' : '') + '\\n</attached_file>',\n    shown: shown.length,\n  }\n}\n\n/** The first `limit` bytes of a stream; stops reading (and releases the stream) once it has them. */\nasync function readHead(stream: AsyncIterable<Uint8Array>, limit: number): Promise<Uint8Array> {\n  const chunks: Uint8Array[] = []\n  let total = 0\n  for await (const chunk of stream) {\n    chunks.push(chunk)\n    total += chunk.length\n    if (total >= limit) break\n  }\n  const out = new Uint8Array(Math.min(total, limit))\n  let offset = 0\n  for (const chunk of chunks) {\n    if (offset >= out.length) break\n    const piece = chunk.subarray(0, out.length - offset)\n    out.set(piece, offset)\n    offset += piece.length\n  }\n  return out\n}\n\n/**\n * UTF-8 text, or null for anything that is not (a NUL byte or invalid UTF-8). A cut in\n * the middle of a character at the read limit is not counted as invalid.\n */\nfunction decodeText(bytes: Uint8Array, cut: boolean): string | null {\n  if (bytes.includes(0)) return null\n  try {\n    return new TextDecoder('utf-8', { fatal: true }).decode(bytes, { stream: cut })\n  } catch {\n    return null\n  }\n}\n\nfunction escapeAttribute(value: string): string {\n  return value.replace(/[\"<>\\n\\r]/gu, ' ')\n}\n"
    },
    {
      "path": "src/client/refine.ts",
      "content": "/**\n * The refine flow, as store transitions. A draft goes to the host; the reply either rewrites\n * the composer, fails, or opens the follow-up panel, whose answers continue the same refine.\n * The composer button, the status bubble and the panel all drive refines through these\n * functions, so each step has one implementation.\n *\n * @module dsh-smart-prompt/client/refine\n */\n\nimport { splitCommand } from '../command.js'\nimport type { TFn } from './components.js'\nimport { ENDPOINT, isAbort, postJson, type AnswerBody, type ApiResponse, type Endpoint } from './api.js'\nimport { closeAsk, notify, storeFor, type AskNotice, type AskQuestion, type AskRun, type Idea, type InputActionsFace } from './store.js'\n\n/** `kind` of the pending interaction the follow-up panel is published as. */\nexport const FOLLOW_UP_KIND = 'dsh-smart-prompt-follow-up'\n\n/** The pending interaction that puts the follow-up panel into a session's composer seat. */\nexport interface FollowUpInteraction {\n  readonly kind: typeof FOLLOW_UP_KIND\n  /** The host's run id: a new refine gets a new key. */\n  readonly key: string\n  readonly sessionId: string\n}\n\n/** The host's publisher: shows one interaction, returns the function that withdraws it. */\nexport type FollowUpPublisher = (interaction: FollowUpInteraction, delegate: () => Promise<void>) => () => void\n\n/**\n * Set once the uiSession mount ran. Refines ask for follow-up questions only while it is set:\n * without it the panel could not be shown, and the host would wait for answers forever.\n */\nlet publisher: FollowUpPublisher | null = null\n\n/**\n * Make follow-up questions possible.\n *\n * @param publish - the host's pending-interaction publisher.\n * @returns undoes it (refines started after that ask no questions).\n */\nexport function providePublisher(publish: FollowUpPublisher): () => void {\n  publisher = publish\n  return () => { if (publisher === publish) publisher = null }\n}\n\n/**\n * The interaction if it is this plugin's follow-up panel, else null (the composer-chain\n * selector: another domain's interaction leaves the seat to its own entry).\n *\n * @param value - a session's current pending interaction (any domain's).\n */\nexport function asFollowUp(value: unknown): FollowUpInteraction | null {\n  if (typeof value !== 'object' || value === null) return null\n  const { kind, key, sessionId } = value as { kind?: unknown; key?: unknown; sessionId?: unknown }\n  return kind === FOLLOW_UP_KIND && typeof key === 'string' && typeof sessionId === 'string' ? value as FollowUpInteraction : null\n}\n\n/**\n * Localized copy for a failure reply: the copy for its code, else the host's own message,\n * else the generic failure.\n */\nfunction failureText(data: ApiResponse, t: TFn): string {\n  const key = 'err_' + (typeof data.code === 'string' ? data.code : 'UNKNOWN')\n  const localized = t(key)\n  if (localized !== key) return localized\n  return typeof data.message === 'string' && data.message !== '' ? data.message : t('err_UNKNOWN')\n}\n\n/** Localized copy for a request that never got a reply. */\nfunction transportFailureText(error: unknown, t: TFn): string {\n  return isAbort(error) ? t('err_ABORTED') : t('err_UPSTREAM')\n}\n\n/** End the refine as failed. The draft is untouched; `backup` keeps the request's draft for Retry. */\nfunction fail(sessionId: string, message: string): void {\n  closeAsk(sessionId)\n  const latest = storeFor(sessionId)\n  latest.phase = 'error'\n  latest.error = message\n  latest.controller = null\n  notify(sessionId)\n}\n\n/** The follow-up questions of a reply, or null when it carries none (or a malformed set). */\nfunction parseAsk(value: unknown): { runId: string; questions: { id: string; question: string }[] } | null {\n  if (typeof value !== 'object' || value === null) return null\n  const { runId, questions } = value as { runId?: unknown; questions?: unknown }\n  if (typeof runId !== 'string' || runId === '' || !Array.isArray(questions)) return null\n  const valid = questions.flatMap((item) => {\n    const question = item as { id?: unknown; question?: unknown } | null\n    return typeof question === 'object' && question !== null && typeof question.id === 'string' && typeof question.question === 'string'\n      ? [{ id: question.id, question: question.question }]\n      : []\n  })\n  return valid.length > 0 ? { runId, questions: valid } : null\n}\n\n/** The well-formed ideas of a `/stardea` reply. */\nfunction parseIdeas(value: readonly unknown[]): Idea[] {\n  return value.flatMap((item) => {\n    const idea = item as { id?: unknown; text?: unknown; source?: unknown } | null\n    return typeof idea === 'object' && idea !== null && typeof idea.id === 'string' && typeof idea.text === 'string' && idea.text !== ''\n      ? [{ id: idea.id, text: idea.text, source: typeof idea.source === 'string' ? idea.source : '' }]\n      : []\n  })\n}\n\n/** Tell the host to drop a waiting refine. The panel is gone either way, so the reply is not needed. */\nfunction postCancel(runId: string): Promise<void> {\n  return postJson(ENDPOINT.cancel, { runId }).then(() => undefined, () => undefined)\n}\n\n/** Cancel the refine whose panel is open: the refine ends as cancelled, the draft untouched. */\nfunction cancelAsk(sessionId: string, t: TFn): Promise<void> {\n  const run = storeFor(sessionId).ask\n  if (run === null) return Promise.resolve()\n  fail(sessionId, t('err_ABORTED'))\n  return postCancel(run.runId)\n}\n\n/** Show the follow-up panel for a refine the host keeps waiting until it is answered. */\nfunction openAsk(sessionId: string, reply: { runId: string; questions: { id: string; question: string }[] }, actions: InputActionsFace, t: TFn): void {\n  const publish = publisher\n  if (publish === null) {\n    // The seat went away while the request ran (plugin teardown): nothing can answer.\n    void postCancel(reply.runId)\n    fail(sessionId, t('err_ABORTED'))\n    return\n  }\n  const run: AskRun = {\n    runId: reply.runId,\n    questions: reply.questions.map(({ id, question }) => ({ id, question, ideas: [], selected: new Set<string>(), custom: '', pending: false, notice: null })),\n    actions,\n    stardea: new AbortController(),\n    unpublish: () => {},\n  }\n  const state = storeFor(sessionId)\n  state.ask = run\n  // Nothing is in flight while the panel is open; the busy star cancels through /cancel instead.\n  state.controller = null\n  try {\n    // The panel cannot be handed to another UI, so a host teardown that takes it away cancels the refine.\n    run.unpublish = publish({ kind: FOLLOW_UP_KIND, key: run.runId, sessionId }, () => (storeFor(sessionId).ask === run ? cancelAsk(sessionId, t) : Promise.resolve()))\n  } catch (error) {\n    console.error('[dsh-smart-prompt] follow-up panel could not be shown', error)\n    void cancelAsk(sessionId, t)\n    return\n  }\n  notify(sessionId)\n}\n\n/** Apply one refine reply: `/improve` and `/answer` answer in the same shapes. */\nfunction settle(sessionId: string, data: ApiResponse, actions: InputActionsFace, t: TFn): void {\n  if (data.ok === true && typeof data.text === 'string' && data.text !== '') {\n    const latest = storeFor(sessionId)\n    latest.enhanced = data.text\n    latest.meta = data.meta !== undefined ? data.meta : null\n    latest.phase = 'done'\n    latest.controller = null\n    actions.setDraft(data.text)\n    notify(sessionId)\n    return\n  }\n  const ask = data.ok === true ? parseAsk(data.ask) : null\n  if (ask !== null) openAsk(sessionId, ask, actions, t)\n  else fail(sessionId, failureText(data, t))\n}\n\n/** Send one refine request and apply its reply; aborting `controller` cancels the refine. */\nasync function send(sessionId: string, controller: AbortController, endpoint: Endpoint, body: unknown, actions: InputActionsFace, t: TFn): Promise<void> {\n  try {\n    settle(sessionId, await postJson(endpoint, body, controller.signal), actions, t)\n  } catch (error) {\n    fail(sessionId, transportFailureText(error, t))\n  }\n}\n\n/**\n * Send one draft to the host and write the result into the composer.\n *\n * Shared by the composer button and both Retries, so all follow the same state transitions:\n * busy -> done (draft replaced, `backup` keeps `text`), busy -> error (draft untouched), or\n * busy with the follow-up panel open, which continues the refine through {@link submitAsk}.\n * A slash-command draft with no body is ignored.\n *\n * @param sessionId - the session whose composer is rewritten.\n * @param text - the draft to enhance; becomes the Revert target.\n * @param actions - composer actions used to write the result.\n * @param t - localized copy lookup for failure messages.\n */\nexport function runImprove(sessionId: string, text: string, actions: InputActionsFace, t: TFn): void {\n  if (splitCommand(text).body === '') return\n  const current = storeFor(sessionId)\n  const controller = new AbortController()\n  current.controller = controller\n  current.phase = 'busy'\n  current.error = null\n  current.backup = text\n  current.meta = null\n  current.enhanced = ''\n  // A new refine gets its own success bubble.\n  current.doneBubbleOwner = null\n  notify(sessionId)\n\n  // The attachments in the composer now: they stay there whatever the refine does.\n  const attachmentIds = current.attachmentIds\n  const serialize = current.serialize\n\n  void (async () => {\n    let attachments: readonly unknown[] = []\n    try {\n      if (attachmentIds.length > 0 && serialize !== null) attachments = await serialize(attachmentIds)\n    } catch {\n      // Typically a file still uploading: refining without it would ignore what the user attached.\n      fail(sessionId, controller.signal.aborted ? t('err_ABORTED') : t('err_ATTACHMENTS'))\n      return\n    }\n    // No mode: the host reads it from the plugin settings page.\n    await send(sessionId, controller, ENDPOINT.improve, {\n      sessionId,\n      text,\n      ...(attachments.length > 0 ? { attachments } : {}),\n      ...(publisher !== null ? { interactive: true } : {}),\n    }, actions, t)\n  })()\n}\n\n/**\n * Cancel the session's running refine, whatever it waits on: the open panel's run through\n * `/cancel`, otherwise the request in flight. Both end with the cancelled failure bubble.\n */\nexport function cancelRefine(sessionId: string, t: TFn): void {\n  const current = storeFor(sessionId)\n  if (current.ask !== null) void cancelAsk(sessionId, t)\n  else if (current.controller !== null) current.controller.abort()\n}\n\n/** Every question's answer: its ticked idea texts (in list order) and own words; blank questions are left out. */\nfunction answersOf(run: AskRun): AnswerBody[] {\n  return run.questions.flatMap((question) => {\n    const selected = question.ideas.filter((idea) => question.selected.has(idea.id)).map((idea) => idea.text)\n    const custom = question.custom.trim()\n    if (selected.length === 0 && custom === '') return []\n    return [{ id: question.id, selected, ...(custom !== '' ? { custom } : {}) }]\n  })\n}\n\n/** Tick or untick one idea of an open question. */\nexport function toggleIdea(sessionId: string, question: AskQuestion, ideaId: string): void {\n  if (!question.selected.delete(ideaId)) question.selected.add(ideaId)\n  notify(sessionId)\n}\n\n/** Record the user's own words for an open question. */\nexport function setOwnWords(sessionId: string, question: AskQuestion, text: string): void {\n  question.custom = text\n  notify(sessionId)\n}\n\n/** `/answer` with no answers: the host keeps the first rewrite. */\nconst NO_ANSWERS = (): AnswerBody[] => []\n\n/** Close the panel and continue the refine with the chosen answers. */\nfunction sendAnswers(sessionId: string, pick: (run: AskRun) => AnswerBody[], t: TFn): void {\n  const state = storeFor(sessionId)\n  const run = state.ask\n  if (run === null) return\n  const answers = pick(run)\n  closeAsk(sessionId)\n  // Aborting this request (the busy star) cancels the refine.\n  const controller = new AbortController()\n  state.controller = controller\n  notify(sessionId)\n  void send(sessionId, controller, ENDPOINT.answer, { runId: run.runId, answers }, run.actions, t)\n}\n\n/** Submit the panel's answers. */\nexport function submitAsk(sessionId: string, t: TFn): void {\n  sendAnswers(sessionId, answersOf, t)\n}\n\n/** Skip every question; the refine keeps its first rewrite. */\nexport function skipAsk(sessionId: string, t: TFn): void {\n  sendAnswers(sessionId, NO_ANSWERS, t)\n}\n\n/**\n * Ask the host for more ideas for one open question and append them after the existing ones.\n * A failure, or a reply with nothing new, leaves a note under the question and keeps its ideas.\n *\n * @param sessionId - the session whose panel shows the question.\n * @param question - the question, as held by the open run.\n * @param t - localized copy lookup.\n */\nexport async function requestIdeas(sessionId: string, question: AskQuestion, t: TFn): Promise<void> {\n  const run = storeFor(sessionId).ask\n  if (run === null || question.pending || !run.questions.includes(question)) return\n  question.pending = true\n  question.notice = null\n  notify(sessionId)\n  let notice: AskNotice | null = null\n  try {\n    const data = await postJson(ENDPOINT.stardea, { runId: run.runId, questionId: question.id }, run.stardea.signal)\n    if (data.ok === true && Array.isArray(data.ideas)) {\n      // Ideas are keyed by id (list keys, ticks), so an id seen before is never added twice.\n      const known = new Set(question.ideas.map((idea) => idea.id))\n      const before = question.ideas.length\n      for (const idea of parseIdeas(data.ideas)) {\n        if (known.has(idea.id)) continue\n        known.add(idea.id)\n        question.ideas.push(idea)\n      }\n      // The host drops ideas that repeat earlier ones, so a click can come back empty.\n      if (question.ideas.length === before) notice = { kind: 'info', text: t('stardeaNoMore') }\n    } else {\n      notice = { kind: 'error', text: failureText(data, t) }\n    }\n  } catch (error) {\n    notice = { kind: 'error', text: transportFailureText(error, t) }\n  }\n  question.pending = false\n  question.notice = notice\n  notify(sessionId)\n}\n"
    },
    {
      "path": "src/config.ts",
      "content": "/**\n * Plugin configuration: schema, defaults, and defensive resolution.\n *\n * @module dsh-smart-prompt/config\n */\n\nimport { homedir } from 'node:os'\nimport { join } from 'node:path'\nimport z from '@deepseek-ai/schemastery'\nimport {\n  DEFAULT_LOOKUP_ROUNDS, DEFAULT_MAX_QUESTIONS, DEFAULT_MODE, DEFAULT_MODEL_SOURCE, DEFAULT_STARDEA_IDEAS, DEFAULT_STARDEA_ROUNDS,\n  DEFAULT_STARDEA_WEB_SEARCH, MAX_LOOKUP_ROUNDS, MAX_STARDEA_IDEAS, MAX_STARDEA_ROUNDS, MIN_LOOKUP_ROUNDS, MIN_MAX_QUESTIONS,\n  MIN_STARDEA_IDEAS, MIN_STARDEA_ROUNDS, MODE_VALUES, MODEL_SOURCE_VALUES, isOneOf, type Mode, type ModelSource,\n} from './settings-fields.js'\nimport { asRecord, trimmedText } from './values.js'\n\nexport { DEFAULT_LOOKUP_ROUNDS, DEFAULT_MAX_QUESTIONS, MAX_LOOKUP_ROUNDS, MODE_VALUES, MODEL_SOURCE_VALUES, type Mode, type ModelSource }\n\n/** Values the settings page edits; re-read on every request so a save applies at once. */\nexport interface LiveSettings {\n  readonly mode: Mode\n  readonly modelSource: ModelSource\n  /** Dedicated route; both empty unless the user picked one. */\n  readonly provider: string\n  readonly model: string\n  /** Effort for the dedicated model; empty sends none (adapter default). */\n  readonly reasoningEffort: string\n  /** Most follow-up questions one refinement may ask about missing information. */\n  readonly maxQuestions: number\n  /** Most rounds of session search/read the rewrite may run; 0 turns its lookups off. */\n  readonly sessionLookupRounds: number\n  /** Most new ideas one Stardea click returns. */\n  readonly stardeaIdeas: number\n  /** Most lookup rounds one Stardea click may run; 0 proposes ideas without searching. */\n  readonly stardeaRounds: number\n  /** Whether Stardea may search the web (through DSH's web search service). */\n  readonly stardeaWebSearch: boolean\n}\n\n/** Light-mode length ceiling: the rewrite may reach this multiple of the draft. */\nexport const DEFAULT_LIGHT_MAX_RATIO = 2\n/**\n * Standard-mode length ceiling. 0 = uncapped (user decision): restructuring a draft\n * that needed follow-up answers was refused too often; set a positive ratio to cap it.\n */\nexport const DEFAULT_STANDARD_MAX_RATIO = 0\n\n/**\n * Defaults of the loader-only fields. The schema declares them and `resolveConfig` falls\n * back to them, so both read this one table.\n */\nconst DEFAULTS = Object.freeze({\n  lightMaxRatio: DEFAULT_LIGHT_MAX_RATIO,\n  standardMaxRatio: DEFAULT_STANDARD_MAX_RATIO,\n  acceptanceCriteria: false,\n  temperature: 0.3,\n  // Output-token cap of one call. Reasoning models count their thinking against it, so a\n  // small cap can be spent on thinking alone and the reply arrives with no text (seen on\n  // opencode's deepseek-v4.1-flash-free at 8192). 32000 is that model's catalog output\n  // limit; the host lowers it further when the context window leaves less room.\n  maxTokens: 32000,\n  timeoutMs: 180000,\n  maxInputChars: 20000,\n  contextTurns: 3,\n  contextChars: 6000,\n  smartContext: true,\n  fidelityGate: true,\n  lengthGate: true,\n  // Size limit of the workspace knowledge file (SMART-PROMPT.md), in characters; 0 turns it off.\n  // Read in full at the start of every refinement, so it is kept to a small share of the prompt.\n  knowledgeChars: 4000,\n  // 'low' by default: a rewrite is a shallow task, and reasoning models at the\n  // agent's default effort (often max) can burn minutes or exhaust a small token\n  // budget on thinking before any answer text arrives.\n  reasoningEffort: 'low',\n  logFailures: true,\n})\n\n/** Runtime configuration after defaults are applied. */\nexport interface ResolvedConfig {\n  readonly defaultMode: Mode\n  readonly lightMaxRatio: number\n  readonly standardMaxRatio: number\n  readonly acceptanceCriteria: boolean\n  readonly temperature: number\n  readonly maxTokens: number\n  readonly timeoutMs: number\n  readonly maxInputChars: number\n  readonly contextTurns: number\n  readonly contextChars: number\n  readonly smartContext: boolean\n  readonly fidelityGate: boolean\n  readonly lengthGate: boolean\n  /** Size limit of the workspace knowledge file in characters; 0 turns the file off. */\n  readonly knowledgeChars: number\n  readonly provider: string\n  readonly model: string\n  readonly reasoningEffort: string\n  readonly logFailures: boolean\n}\n\n/** Loader schema — every key optional. `.volatile()` is what puts a field on the DSH settings page (0.2.0+). */\nexport const Config = z.object({\n  defaultMode: z.union(MODE_VALUES).default(DEFAULT_MODE).volatile(),\n  modelSource: z.union(MODEL_SOURCE_VALUES).default(DEFAULT_MODEL_SOURCE).volatile(),\n  lightMaxRatio: z.number().default(DEFAULTS.lightMaxRatio),\n  standardMaxRatio: z.number().default(DEFAULTS.standardMaxRatio),\n  acceptanceCriteria: z.boolean().default(DEFAULTS.acceptanceCriteria),\n  temperature: z.number().default(DEFAULTS.temperature),\n  maxTokens: z.number().default(DEFAULTS.maxTokens),\n  timeoutMs: z.number().default(DEFAULTS.timeoutMs),\n  maxInputChars: z.number().default(DEFAULTS.maxInputChars),\n  contextTurns: z.number().default(DEFAULTS.contextTurns),\n  contextChars: z.number().default(DEFAULTS.contextChars),\n  smartContext: z.boolean().default(DEFAULTS.smartContext),\n  fidelityGate: z.boolean().default(DEFAULTS.fidelityGate),\n  lengthGate: z.boolean().default(DEFAULTS.lengthGate),\n  knowledgeChars: z.number().default(DEFAULTS.knowledgeChars),\n  provider: z.string().default('').volatile(),\n  model: z.string().default('').volatile(),\n  dedicatedReasoningEffort: z.string().default('').volatile(),\n  maxQuestions: z.natural().min(MIN_MAX_QUESTIONS).default(DEFAULT_MAX_QUESTIONS).volatile(),\n  sessionLookupRounds: z.natural().max(MAX_LOOKUP_ROUNDS).default(DEFAULT_LOOKUP_ROUNDS).volatile(),\n  stardeaIdeas: z.natural().min(MIN_STARDEA_IDEAS).max(MAX_STARDEA_IDEAS).default(DEFAULT_STARDEA_IDEAS).volatile(),\n  stardeaRounds: z.natural().max(MAX_STARDEA_ROUNDS).default(DEFAULT_STARDEA_ROUNDS).volatile(),\n  stardeaWebSearch: z.boolean().default(DEFAULT_STARDEA_WEB_SEARCH).volatile(),\n  reasoningEffort: z.string().default(DEFAULTS.reasoningEffort),\n  logFailures: z.boolean().default(DEFAULTS.logFailures),\n})\n\n/** Read one field that may be a volatile reference (`.get()`) or a plain value. */\nfunction live(value: unknown): unknown {\n  return value !== null && typeof value === 'object' && typeof (value as { get?: unknown }).get === 'function'\n    ? (value as { get(): unknown }).get()\n    : value\n}\n\n/**\n * Resolve the settings-page fields at call time.\n *\n * @param raw - config as handed to `apply` (volatile references or plain values).\n * @returns the current mode, model source, and dedicated route.\n */\nexport function readLiveSettings(raw: unknown): LiveSettings {\n  const c = asRecord(raw)\n  const mode = live(c.defaultMode)\n  const source = live(c.modelSource)\n  return {\n    mode: isOneOf(mode, MODE_VALUES) ? mode : DEFAULT_MODE,\n    modelSource: isOneOf(source, MODEL_SOURCE_VALUES) ? source : DEFAULT_MODEL_SOURCE,\n    provider: trimmedText(live(c.provider)),\n    model: trimmedText(live(c.model)),\n    reasoningEffort: trimmedText(live(c.dedicatedReasoningEffort)),\n    maxQuestions: wholeInRange(live(c.maxQuestions), MIN_MAX_QUESTIONS, Infinity, DEFAULT_MAX_QUESTIONS),\n    sessionLookupRounds: wholeInRange(live(c.sessionLookupRounds), MIN_LOOKUP_ROUNDS, MAX_LOOKUP_ROUNDS, DEFAULT_LOOKUP_ROUNDS),\n    stardeaIdeas: wholeInRange(live(c.stardeaIdeas), MIN_STARDEA_IDEAS, MAX_STARDEA_IDEAS, DEFAULT_STARDEA_IDEAS),\n    stardeaRounds: wholeInRange(live(c.stardeaRounds), MIN_STARDEA_ROUNDS, MAX_STARDEA_ROUNDS, DEFAULT_STARDEA_ROUNDS),\n    stardeaWebSearch: flag(live(c.stardeaWebSearch), DEFAULT_STARDEA_WEB_SEARCH),\n  }\n}\n\n/** A whole number within the schema's bounds, else the default (a hand-edited file may hold anything). */\nfunction wholeInRange(value: unknown, min: number, max: number, fallback: number): number {\n  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max ? value : fallback\n}\n\nfunction positive(value: unknown, fallback: number): number {\n  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : fallback\n}\n\nfunction nonNegative(value: unknown, fallback: number): number {\n  return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : fallback\n}\n\nfunction flag(value: unknown, fallback: boolean): boolean {\n  return typeof value === 'boolean' ? value : fallback\n}\n\n/**\n * Apply defaults and reject nonsense without ever throwing at the user.\n *\n * A misconfigured plugin must still load: every field falls back independently.\n *\n * @param raw - config as handed to `apply` by the loader (possibly undefined).\n * @returns a complete, safe configuration.\n */\nexport function resolveConfig(raw: unknown): ResolvedConfig {\n  const c = asRecord(raw)\n  // The settings-page fields have one resolver; this snapshot only mirrors it.\n  const settings = readLiveSettings(raw)\n  const effort = trimmedText(c.reasoningEffort)\n  return {\n    defaultMode: settings.mode,\n    lightMaxRatio: nonNegative(c.lightMaxRatio, DEFAULTS.lightMaxRatio),\n    standardMaxRatio: nonNegative(c.standardMaxRatio, DEFAULTS.standardMaxRatio),\n    acceptanceCriteria: flag(c.acceptanceCriteria, DEFAULTS.acceptanceCriteria),\n    temperature: nonNegative(c.temperature, DEFAULTS.temperature),\n    maxTokens: positive(c.maxTokens, DEFAULTS.maxTokens),\n    timeoutMs: positive(c.timeoutMs, DEFAULTS.timeoutMs),\n    maxInputChars: positive(c.maxInputChars, DEFAULTS.maxInputChars),\n    contextTurns: nonNegative(c.contextTurns, DEFAULTS.contextTurns),\n    contextChars: nonNegative(c.contextChars, DEFAULTS.contextChars),\n    smartContext: flag(c.smartContext, DEFAULTS.smartContext),\n    fidelityGate: flag(c.fidelityGate, DEFAULTS.fidelityGate),\n    lengthGate: flag(c.lengthGate, DEFAULTS.lengthGate),\n    knowledgeChars: nonNegative(c.knowledgeChars, DEFAULTS.knowledgeChars),\n    provider: settings.provider,\n    model: settings.model,\n    reasoningEffort: effort !== '' ? effort : DEFAULTS.reasoningEffort,\n    logFailures: flag(c.logFailures, DEFAULTS.logFailures),\n  }\n}\n\n/** Ceiling for one mode. Light has its own; every restructuring mode (standard, detailed) shares standard's. */\nexport function maxRatioFor(config: ResolvedConfig, mode: Mode): number {\n  return mode === 'light' ? config.lightMaxRatio : config.standardMaxRatio\n}\n\n/** `$DSH_HOME` (honouring an explicit env var) — web processes can disagree with homedir(). */\nexport function dshHome(): string {\n  const fromEnv = process.env.DSH_HOME\n  return fromEnv !== undefined && fromEnv !== '' ? fromEnv : join(homedir(), '.dsh')\n}\n"
